template:
struct Inventory {
    gold: u32,
    label: String,
}

impl Inventory {
    fn add_gold(&mut self, amount: u32) {
        self.gold += amount;
    }
}

fn print_and_add(inv: &mut Inventory) {
    let name = ⟦name_expr⟧;
    ⟦update_expr⟧;
    println!("{name}: {}", inv.gold);
}

fn main() {
    let mut inv = Inventory { gold: 50, label: String::from("Vault") };
    print_and_add(&mut inv);
}

tests:
#[test]
fn updates_gold() {
    let mut inv = Inventory { gold: 50, label: String::from("Vault"), };
    print_and_add(&mut inv);
    assert_eq!(inv.gold, 60);
}
